function cookie(e){let o=e+"=",t=document,n=()=>{let e=new RegExp("(?:; *)?"+o+"([^;]*)(?:;|$)").exec(t.cookie);null!==e&&decodeURIComponent(e[1])},c=(e,n=NaN)=>t.cookie=o+encodeURIComponent(e)+";path=/"+(isNaN(n)?"":";expires="+new Date(Date.now()+1e3*n).toUTCString());return{value:n,set:c,delete:()=>c("",0),toString:n}}